import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { UseCaseLanding } from "@/components/marketing/UseCaseLanding";
import type { PlanCard } from "@/components/marketing/PricingGrid";
import { APP_URL, FaqJsonLd, ProductOffersJsonLd } from "@/components/marketing/StructuredData";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import type { PreviewGame } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import Link from "next/link";
import {
  findCombo,
  buildLanding,
  findRegionCombo,
  buildRegionLanding,
  LANDING_SLUGS,
  REGION_LANDING_SLUGS,
  type LandingPlan,
  type BuiltLanding,
} from "@/lib/marketing/locationLandings";
import {
  findGameLocationCombo,
  buildGameLocationLanding,
  buildGameLocationPreviewGame,
  findGeneralLocationCombo,
  buildGeneralLocationLanding,
  GAME_LOCATION_SLUGS,
  GENERAL_LOCATION_SLUGS,
  type GamePlanRow,
} from "@/lib/marketing/gameLocationLandings";

/**
 * Programmatic "(location) (service)" marketing landing pages, the region-tier
 * umbrella pages above them, AND (added here) the game-family × location
 * matrix + the general per-location VPS/Game-Server pages that don't already
 * exist via the tables above — see lib/marketing/gameLocationLandings.ts's
 * file doc for the full architecture note.
 *
 * Four data tables, one route: a slug is checked against the region matrix,
 * then the city matrix, then the game×location matrix, then the general
 * new-location matrix — in that order, so nothing here can ever shadow a
 * hand-written static marketing page (which wins at request time anyway) or
 * silently collide with an existing slug. Anything in none of the four falls
 * through to a 404. Real DB rows (VPS `Plan` or, for a game×location combo,
 * that family's real `GamePlan` rows) feed every page's pricing grid and
 * Product rich-result — nothing here is a hardcoded price.
 */

export const dynamic = "force-dynamic";

// Pre-declare every known slug across all four tables so Next can enumerate
// them at build time; unknown slugs are rejected in the page/metadata via
// notFound().
export function generateStaticParams(): Array<{ slug: string }> {
  return [...REGION_LANDING_SLUGS, ...LANDING_SLUGS, ...GAME_LOCATION_SLUGS, ...GENERAL_LOCATION_SLUGS].map((slug) => ({
    slug,
  }));
}

async function loadVpsPlans(): Promise<LandingPlan[]> {
  return db.plan.findMany({
    where: { active: true },
    orderBy: { sortOrder: "asc" },
  });
}

/**
 * Real, active `GamePlan` rows for one family, mapped both to the plain
 * `GamePlanRow[]` the copy builder reads for prose (RAM/slots/price only)
 * and to full `PlanCard[]` for the pricing grid — `bandwidthTB`/`storageTier`
 * come from each row's real `basePlan` (the actual VPS-grade Plan the game
 * server is provisioned on), never a fabricated number.
 */
async function loadGamePlans(gameFamily: string): Promise<{ rows: GamePlanRow[]; cards: PlanCard[] }> {
  const plans = await db.gamePlan.findMany({
    where: { gameFamily, active: true },
    orderBy: { sortOrder: "asc" },
    include: { basePlan: true },
  });
  const rows: GamePlanRow[] = plans.map((p) => ({
    id: p.id,
    name: p.name,
    ramMB: p.ramMB,
    slots: p.slots,
    priceCents: p.priceCents,
    introPriceCents: p.introPriceCents,
  }));
  const cards: PlanCard[] = plans.map((p) => ({
    id: p.id,
    name: p.name,
    cpuCores: p.cpuCores,
    ramMB: p.ramMB,
    diskGB: p.diskGB,
    bandwidthTB: p.basePlan.bandwidthTB,
    priceCents: p.priceCents,
    storageTier: p.basePlan.storageTier,
    introMonthlyCents: p.introPriceCents,
    slots: p.slots,
  }));
  return { rows, cards };
}

/**
 * Discriminant is NOT "does this page's service key happen to be `game`" —
 * the pre-existing city/region/general-location "game server hosting" pages
 * (e.g. "toronto-game-server-hosting") already price themselves off generic
 * VPS `Plan` rows (same as every other service on those tables) and deploy
 * as `service=vps`, unchanged from before this file existed. Only a genuine
 * per-family combo (e.g. "singapore-minecraft-server-hosting", resolved via
 * `findGameLocationCombo`) prices off that family's real `GamePlan` rows and
 * needs `service="game"` + `gameFamily` wired through to the deploy links.
 */
type Resolved =
  | { kind: "generic"; built: BuiltLanding; plans: LandingPlan[] }
  | {
      kind: "game-family";
      built: BuiltLanding;
      plans: PlanCard[];
      gameFamily: string;
      productName: string;
      /**
       * The GameLandingCombined-ready merge (real pricing + this combo's
       * honesty framing over the game's PREVIEW_GAMES fixture) — see
       * lib/marketing/gameLocationLandings.ts's buildGameLocationPreviewGame
       * doc. `undefined` only if `family` somehow has no PREVIEW_GAMES entry
       * (shouldn't happen for anything in ACTIVE_GAME_FAMILIES), in which case
       * the page below falls back to the generic UseCaseLanding render so a
       * drift between the two lists degrades gracefully instead of 500ing.
       */
      previewGame: PreviewGame | undefined;
    };

async function resolve(slug: string): Promise<Resolved | undefined> {
  const regionCombo = findRegionCombo(slug);
  if (regionCombo) {
    const plans = await loadVpsPlans();
    return { kind: "generic", built: buildRegionLanding(regionCombo, plans), plans };
  }

  const combo = findCombo(slug);
  if (combo) {
    const plans = await loadVpsPlans();
    return { kind: "generic", built: buildLanding(combo, plans), plans };
  }

  const generalCombo = findGeneralLocationCombo(slug);
  if (generalCombo) {
    const plans = await loadVpsPlans();
    return { kind: "generic", built: buildGeneralLocationLanding(generalCombo, plans), plans };
  }

  const gameCombo = findGameLocationCombo(slug);
  if (gameCombo) {
    const { rows, cards } = await loadGamePlans(gameCombo.family);
    const built = buildGameLocationLanding(gameCombo, rows);
    const previewGame = buildGameLocationPreviewGame(gameCombo, cards);
    return { kind: "game-family", built, plans: cards, gameFamily: built.gameFamily, productName: built.productName, previewGame };
  }

  return undefined;
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  const resolved = await resolve(slug);
  if (!resolved) return {};
  const { built } = resolved;

  const url = `${APP_URL}/${slug}`;

  return {
    title: built.metaTitle,
    description: built.metaDescription,
    alternates: { canonical: `/${slug}` },
    openGraph: {
      type: "article",
      title: built.ogTitle,
      description: built.ogDescription,
      url,
    },
    twitter: {
      card: "summary_large_image",
      title: built.ogTitle,
      description: built.ogDescription,
    },
  };
}

export default async function LocationServiceLandingPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const resolved = await resolve(slug);
  if (!resolved) notFound();
  const { built, plans } = resolved;

  const url = `${APP_URL}/${slug}`;

  // BreadcrumbList — helps Google render the Home › <Page> trail and reinforces
  // the page's place in the site. FAQ + Product JSON-LD are emitted below,
  // either by UseCaseLanding (generic pages) or directly here (game-family
  // combos rendered through GameLandingCombined instead), so all three rich
  // results are covered either way.
  const breadcrumb = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: APP_URL },
      { "@type": "ListItem", position: 2, name: built.breadcrumbName, item: url },
    ],
  };

  // Game×location combos render through the SAME flagship template as the
  // ~40 hand-built per-game pages (GameLandingCombined) instead of the
  // generic UseCaseLanding/PricingGrid path — see gameLocationLandings.ts's
  // buildGameLocationPreviewGame. Falls through to the generic branch below
  // if `family` somehow has no PREVIEW_GAMES fixture (shouldn't happen).
  if (resolved.kind === "game-family" && resolved.previewGame) {
    const { built: gameBuilt, previewGame, productName } = resolved;
    return (
      <>
        <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }} />
        <FaqJsonLd items={gameBuilt.content.faq} />
        <ProductOffersJsonLd
          name={productName}
          description={gameBuilt.content.sub}
          url={url}
          offers={resolved.plans.map((p) => ({ name: p.name, price: p.priceCents / 100 }))}
        />

        <GameLandingCombined game={previewGame} reviewBadges={<ReviewBadges />} />

        {/* FAQ + related — carried over from the same content the ~40 static
         * per-game pages ship below GameLandingCombined (e.g. rust-server-
         * hosting/page.tsx), reusing this combo's own honest, location-aware
         * copy from buildGameLocationLanding rather than duplicating it. */}
        <Section tone="base" size="md">
          <SectionTitle eyebrow="FAQ" title="Questions, answered" />
          <div className="mx-auto mt-10 max-w-3xl space-y-3">
            {gameBuilt.content.faq.map((f) => (
              <details key={f.q} className="card group">
                <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                  <span className="flex items-center justify-between gap-4">
                    {f.q}
                    <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                  </span>
                </summary>
                <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
              </details>
            ))}
          </div>
        </Section>

        {gameBuilt.content.related && gameBuilt.content.related.length > 0 && (
          <Section tone="base" size="sm">
            <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
              <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
              {gameBuilt.content.related.map((r) => (
                <Link
                  key={r.href}
                  href={r.href}
                  className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
                >
                  {r.label}
                </Link>
              ))}
            </div>
          </Section>
        )}
      </>
    );
  }

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }}
      />
      <UseCaseLanding
        content={built.content}
        plans={plans as PlanCard[]}
        service={resolved.kind === "game-family" ? "game" : "vps"}
        gameFamily={resolved.kind === "game-family" ? resolved.gameFamily : undefined}
        productName={resolved.kind === "game-family" ? resolved.productName : undefined}
        pageUrl={url}
      />
    </>
  );
}

