/**
 * Game family × location landing pages — the SEO matrix crossing every real,
 * currently-sellable game family against a country/region-level location
 * list ("Singapore Minecraft Server Hosting", "Germany Valheim Server
 * Hosting"), plus general "[Location] VPS Hosting" / "[Location] Game Server
 * Hosting" pages for the locations that don't already have an equivalent
 * page via lib/marketing/locationLandings.ts's existing city/region matrix.
 *
 * ARCHITECTURE: deliberately modeled on `buildLanding`/`buildRegionLanding`
 * in locationLandings.ts (same file this reuses `BuiltLanding`, `listPhrase`
 * and the `presence`-driven honesty discipline from) rather than the 40
 * hand-written `*-server-hosting/page.tsx` files — one data table here, wired
 * into the SAME `app/(marketing)/[slug]/page.tsx` route and the SAME
 * `app/sitemap.ts` loop as the rest of the location matrix, so there is still
 * exactly one route file and the sitemap can never drift from the real slug
 * list. Real pricing is NEVER hardcoded here: every combo's `GamePlanRow[]`
 * (or VPS `LandingPlan[]` for the general pages) is fetched live by the route
 * from `db.gamePlan` / `db.plan` and passed in — this module only turns
 * already-real numbers into prose and a spec note.
 *
 * HONESTY. Nxeon operates exactly two real datacenters — Singapore (`sgp1`)
 * and Falkenstein, Germany (`fsn1`) — see lib/node-regions.ts. Every
 * `GameLocationDef` below carries the same `presence` field as
 * `LocationDef` in locationLandings.ts ("datacenter" | "network" | "market"),
 * set from real geography, not marketing convenience:
 *   - "datacenter": Singapore, Germany (the two real DCs), plus Southeast
 *     Asia and Europe — the immediate regions those two DCs physically sit
 *     inside, so the same honest claim applies at one level up.
 *   - "network": South Korea, Japan, Malaysia, Indonesia, India, United
 *     Kingdom, Netherlands, Australia — genuinely closer to Singapore or
 *     Germany (confirmed against the real REGION_COORDS in
 *     lib/node-regions.ts), so a latency-benefit claim is honestly grounded,
 *     but there is no on-site presence — never claim one.
 *   - "market": United States, North America, Canada — neither real DC is
 *     close to these (per the same coordinate check); copy here is
 *     audience-first only ("served from Singapore or Germany, pick your
 *     nearest region at checkout"), never a latency claim.
 * `gameServerLocationFaq` below is the direct analogue of
 * locationLandings.ts's `serverLocationFaq` — same branch, same refusal to
 * imply a datacenter that doesn't exist.
 */
import type { GameFamily } from "@/lib/games";
import { GAME_DISPLAY, GAME_GENRES } from "@/lib/games";
import { flagEmoji } from "@/lib/flag-emoji";
import { planIntroMonthlyCents } from "@/lib/intro-pricing";
import {
  listPhrase,
  SERVICES,
  type BuiltLanding,
  type LandingPlan,
  type ServiceKey,
} from "@/lib/marketing/locationLandings";
import { PREVIEW_GAMES, type PreviewGame, type PreviewPlan, type PreviewGameKey } from "@/components/marketing/gamelanding/data";
import type { PlanCard } from "@/components/marketing/PricingGrid";

/* ------------------------------------------------------------------ */
/* Locations — country/region granularity (distinct from the city-level */
/* LOCATIONS table in locationLandings.ts; no slug below collides with it) */
/* ------------------------------------------------------------------ */

export type GameLocationDef = {
  slug: string;
  /** Display name, e.g. "South Korea", "Southeast Asia". */
  name: string;
  /** Adjective for the audience, e.g. "Korean". */
  audience: string;
  /** Longer regional phrase for prose. */
  regionLong: string;
  /** Nearby cities/countries for prose variety. */
  nearby: string[];
  /** One factual, geography-grounded sentence used in the intro prose. */
  hub: string;
  /** Same three-value honesty flag as LocationDef in locationLandings.ts. */
  presence: "datacenter" | "network" | "market";
  /** ISO2 code for flagEmoji(), or "" to use the globe fallback below. */
  flag: string;
  /** Present only when `flag` is a deliberate stand-in, not this location's own country — explains the choice (owner asked every location show a real flag; an aggregate has none of its own). */
  flagNote?: string;
};

export const GAME_LOCATIONS: GameLocationDef[] = [
  {
    slug: "singapore",
    name: "Singapore",
    audience: "Singaporean",
    regionLong: "Singapore and the wider city-state market",
    nearby: ["Malaysia", "Indonesia", "the Philippines"],
    hub: "Singapore sits on the submarine-cable crossroads linking Southeast Asia, South Asia, Oceania and East Asia — and it's where Nxeon's own datacenter physically is.",
    presence: "datacenter",
    flag: "sg",
  },
  {
    slug: "southeast-asia",
    name: "Southeast Asia",
    audience: "Southeast Asian",
    regionLong: "Singapore, Malaysia, Indonesia, Thailand, Vietnam and the Philippines",
    nearby: ["Kuala Lumpur", "Jakarta", "Bangkok", "Manila"],
    hub: "Nxeon's real datacenter sits inside Southeast Asia itself — in Singapore — putting it minutes from Kuala Lumpur and Jakarta on the region's densest submarine-cable routes.",
    presence: "datacenter",
    flag: "sg",
    flagNote: "Singapore's flag — our real datacenter for this region is literally inside Southeast Asia, so it's the honest answer, not a stand-in.",
  },
  {
    slug: "south-korea",
    name: "South Korea",
    audience: "Korean",
    regionLong: "South Korea and its huge competitive-gaming and esports market",
    nearby: ["Seoul", "Busan", "Incheon"],
    hub: "South Korea runs some of the densest, fastest broadband in the world, reached over the same well-established East-Asian subsea routes that connect back to Nxeon's Singapore network.",
    presence: "network",
    flag: "kr",
  },
  {
    slug: "japan",
    name: "Japan",
    audience: "Japanese",
    regionLong: "Japan and the broader East-Asian market",
    nearby: ["Tokyo", "Osaka", "Yokohama"],
    hub: "Japan sits on some of the busiest subsea cable landing points in East Asia, with strong, well-peered connectivity back to Nxeon's Singapore network.",
    presence: "network",

    nearby: ["Sydney", "Melbourne", "Brisbane"],
    hub: "Australia connects into Nxeon's Singapore network over the well-established Asia-Pacific subsea routes that also serve Southeast Asia.",
    presence: "network",
    flag: "au",
  },
];

export const GAME_LOCATIONS_BY_SLUG = new Map(GAME_LOCATIONS.map((l) => [l.slug, l]));

/** Flag prefix for display — the owner asked every location to show a real flag; aggregates fall back to a globe rather than an arbitrary country. */
export function locationFlag(loc: GameLocationDef): string {
  return loc.flag ? flagEmoji(loc.flag) : "🌐";
}

/**
 * Locations that already have a general "[Location] VPS/Game Server Hosting"
 * page elsewhere — singapore/germany via the RESERVED/COMBOS city matrix,
 * europe via REGION_COMBOS — so this module must NOT generate a second page
 * at the same slug. Their game-family combo pages (e.g.
 * "singapore-minecraft-server-hosting") are unaffected — those slugs don't
 * collide with anything and are generated normally below.
 */
const GENERAL_PAGE_ALREADY_EXISTS = new Set(["singapore", "germany", "europe"]);

export const GENERAL_PAGE_LOCATIONS: GameLocationDef[] = GAME_LOCATIONS.filter(
  (l) => !GENERAL_PAGE_ALREADY_EXISTS.has(l.slug),
);

/* ------------------------------------------------------------------ */
/* Games — the families that actually qualify: an ACTIVE GamePlan today */
/* ------------------------------------------------------------------ */

/**
 * Verified live against `db.gamePlan.findMany({ where: { active: true } })`
 * on 2026-09-19 (42 families had an active row) — see
 * scripts/_tmp-active-gameplans.ts (run and discarded per the credential/
 * scratch-script convention, not committed). `stationeers` is the one
 * family EXCLUDED despite an active GamePlan row: app/sitemap.ts already
 * documents why its own dedicated game page was withheld — the real
 * didstopia/stationeers-server image never binds a port or creates a world,
 * so a paid SEO funnel into it would be selling a product that doesn't
 * start. Same rule, same exclusion, applied here for consistency instead of
 * re-litigated per location. Re-verify this list (not `GAME_FAMILIES` in
 * lib/games.ts, which includes scaffolded/unsold families too) before
 * adding a new game family's location pages, and drop a family here the
 * moment its last active GamePlan is retired.
 */
export const ACTIVE_GAME_FAMILIES: GameFamily[] = [
  "minecraft", "bedrock", "valheim", "rust", "palworld", "cs2", "terraria",
  "ark", "satisfactory", "projectzomboid", "sdtd", "vrising", "enshrouded",
  "factorio", "gmod", "conan", "unturned", "theforest", "sonsoftheforest",
  "dragonwilds", "sunkenland", "abioticfactor", "corekeeper", "icarus",
  "arkasa", "soulmask", "dst", "vintagestory", "necesse", "tf2", "l4d2",
  "nightingale", "squad", "spaceengineers", "kf2", "barotrauma", "sandstorm",
  "mordhau", "theisle", "eco", "empyrion",
];

/**
 * URL fragment for each family, reused verbatim from its existing dedicated
 * page's own folder name (app/(marketing)/<fragment>-server-hosting) so a
 * combo slug like "germany-<fragment>-server-hosting" reads consistently
 * with the flagship page it links to in `related`, and so nothing here
 * invents a second naming scheme that could drift from the first.
 */
export const GAME_URL_SLUG: Record<GameFamily, string> = {
  minecraft: "minecraft",
  bedrock: "minecraft-bedrock",
