export type GameLocationCombo = { location: GameLocationDef; family: GameFamily; slug: string };

export const GAME_LOCATION_COMBOS: GameLocationCombo[] = GAME_LOCATIONS.flatMap((location) =>
  ACTIVE_GAME_FAMILIES.map((family) => ({
    location,
    family,
    slug: `${location.slug}-${GAME_URL_SLUG[family]}-server-hosting`,
  })),
);

const GAME_LOCATION_COMBO_BY_SLUG = new Map(GAME_LOCATION_COMBOS.map((c) => [c.slug, c]));

export function findGameLocationCombo(slug: string): GameLocationCombo | undefined {
  return GAME_LOCATION_COMBO_BY_SLUG.get(slug);
}

export const GAME_LOCATION_SLUGS: string[] = GAME_LOCATION_COMBOS.map((c) => c.slug);

function gameRelatedLinks(combo: GameLocationCombo): { label: string; href: string }[] {
  const { location: loc, family } = combo;
  const otherLocations = GAME_LOCATIONS.filter((l) => l.slug !== loc.slug)
    .slice(0, 3)
    .map((l) => ({ label: `${l.name} ${gameName(family)} Hosting`, href: `/${l.slug}-${GAME_URL_SLUG[family]}-server-hosting` }));
  return [
    { label: `${gameName(family)} Server Hosting`, href: `/${GAME_URL_SLUG[family]}-server-hosting` },
    ...otherLocations,
    { label: "All game servers", href: "/game-servers" },
    { label: "Pricing", href: "/pricing" },
  ];
}

/**
 * Build the unique landing content for one (game family × location) combo.
 * `plans` is the family's real, active `GamePlan` rows (fetched by the
 * route) — every number quoted below (from-price, RAM range, slot range)
 * comes straight from them.
 */
export function buildGameLocationLanding(
  combo: GameLocationCombo,
  plans: GamePlanRow[],

 *     from live `GamePlan`/basePlan rows via `buildRealPreviewPlans` above —
 *     this is what keeps the known price-drift bug (PREVIEW_GAMES figures
 *     going stale vs the real GamePlan table, already hit once for palworld)
 *     from ever reappearing on the 615 game×location pages.
 *   - location-specific fields (`region`, `trustLatencyLabel`, `locationNote`,
 *     `fromPrice`) are overridden from this combo's real `GameLocationDef` —
 *     honesty framing reused VERBATIM from `loc.hub`, never re-templated.
 *
 * Returns `undefined` only if `family` has no `PREVIEW_GAMES` fixture at all
 * (shouldn't happen for anything in `ACTIVE_GAME_FAMILIES` — every family
 * there has an entry, Minecraft included as of 2026-09-19 — but the route
 * checks this and falls back rather than throwing if the two lists ever
 * drift apart again).
 */
export function buildGameLocationPreviewGame(combo: GameLocationCombo, cards: PlanCard[]): PreviewGame | undefined {
  const { location: loc, family } = combo;
  const base = PREVIEW_GAMES[family as PreviewGameKey] as PreviewGame | undefined;
  if (!base) return undefined;

  const plans = buildRealPreviewPlans(base.name, cards);
  const fromPrice = plans.length
    ? money(Math.min(...cards.map((p) => p.introMonthlyCents ?? planIntroMonthlyCents(p) ?? p.priceCents)))
    : base.fromPrice;

  return {
    ...base,
    region: regionTagLabel(loc),
    fromPrice,
    plans: plans.length ? plans : base.plans,
    trustLatencyLabel: trustStripLabel(loc),
    locationNote: { flagCode: loc.flag, text: loc.hub },
    deployRegion: nearestRealRegion(loc),
  };
}

