export type GeneralLocationCombo = { location: GameLocationDef; service: Extract<ServiceKey, "vps" | "game">; slug: string };

const GENERAL_SERVICES = SERVICES.filter((s) => s.key === "vps" || s.key === "game");

export const GENERAL_LOCATION_COMBOS: GeneralLocationCombo[] = GENERAL_PAGE_LOCATIONS.flatMap((location) =>
  GENERAL_SERVICES.map((service) => ({
    location,
    service: service.key as Extract<ServiceKey, "vps" | "game">,
    slug: `${location.slug}-${service.urlPart}`,
  })),
);

const GENERAL_LOCATION_COMBO_BY_SLUG = new Map(GENERAL_LOCATION_COMBOS.map((c) => [c.slug, c]));

export function findGeneralLocationCombo(slug: string): GeneralLocationCombo | undefined {
  return GENERAL_LOCATION_COMBO_BY_SLUG.get(slug);
}

export const GENERAL_LOCATION_SLUGS: string[] = GENERAL_LOCATION_COMBOS.map((c) => c.slug);

function generalRelatedLinks(combo: GeneralLocationCombo): { label: string; href: string }[] {
  const { location: loc, service } = combo;
  const svcDef = SERVICES.find((s) => s.key === service)!;
  const sibling = service === "vps" ? SERVICES.find((s) => s.key === "game")! : SERVICES.find((s) => s.key === "vps")!;
  return [
    { label: `${loc.name} ${sibling.label}`, href: `/${loc.slug}-${sibling.urlPart}` },
    svcDef.hub,
    { label: "Pricing", href: "/pricing" },
  ];
}

/**
 * Build the general (location × vps|game) landing content for a
 * `GAME_LOCATIONS` entry that has no page yet. `plans` are real, active VPS
 * `Plan` rows (same `LandingPlan` shape and same `db.plan.findMany` fetch as
 * every page in locationLandings.ts) — this is the generic "from $X/mo"
 * anchor, matching how the existing city-level "game" service pages already
 * price themselves off the base VPS plan list rather than one specific game.
 */
export function buildGeneralLocationLanding(combo: GeneralLocationCombo, plans: LandingPlan[]): BuiltLanding {
  const { location: loc, service } = combo;
  const from = fromLabelVps(plans);
  const near3 = listPhrase(loc.nearby.slice(0, 3));
  const flag = locationFlag(loc);
  const lowPing = canClaimLatency(loc);
  const isGame = service === "game";

  const metaTitle = isGame
    ? `${flag} ${loc.name} Game Server Hosting — ${lowPing ? "Low-Ping" : "Managed"} Game Servers, from ${from}/mo`
    : `${flag} ${loc.name} VPS Hosting — Cloud VPS for ${loc.regionLong}, from ${from}/mo`;
  const metaDescription = isGame
    ? `${loc.name} game server hosting for ${loc.regionLong}. Dedicated, game-ready servers with full file access, DDoS protection and instant setup. From ${from}/mo.`
    : `${loc.name} VPS hosting for ${loc.regionLong}. Full-root NVMe cloud servers with a dedicated IPv4, DDoS protection, daily backups and one-click deploys. From ${from}/mo.`;

  const content = isGame
    ? {
        eyebrow: `${flag} ${loc.name} game server hosting`,
        title: lowPing ? `Low-ping game servers for` : `Reliable game servers for`,
        highlight: loc.name,
        sub: `Dedicated, game-ready servers ${lowPing ? "aimed at" : "built for"} players across ${loc.regionLong} — full file access, DDoS protection and instant setup, from ${from}/mo.`,
        intro: [
          `Ping decides the game. ${loc.hub}`,
          `Nxeon runs over 40 game families on the same full-root NVMe platform: dedicated CPU and memory per server, full file access for mods and configs, always-on DDoS protection, and instant setup so your world is online in minutes.`,
          `Whether it's Minecraft, Rust, Valheim, ARK, CS2 or dozens of other titles, you get real resources and real control for ${articleFor(loc.audience)} ${loc.audience} player base across ${near3} — pick your game from the full catalog and deploy in minutes.`,
        ],
        whyTitle: `Built for ${loc.name} game servers`,
        why: [
          { title: lowPing ? `Built for ${loc.name}` : `Priced for ${loc.name}`, body: lowPing ? `Copy and region guidance tuned for ${articleFor(loc.audience)} ${loc.audience} audience across ${near3}.` : `Region guidance tuned for ${articleFor(loc.audience)} ${loc.audience} audience — pick your nearest of Singapore or Germany at checkout.` },
          { title: "Dedicated resources", body: "Guaranteed CPU and RAM per server on enterprise NVMe — no noisy neighbours eating your tick rate." },
          { title: "Full file access", body: "Upload mods, plugins and configs directly — whatever your title needs." },
          { title: "DDoS protection included", body: "Always-on DDoS mitigation with a managed firewall keeps your server up." },
          { title: "Instant setup", body: "Your world is provisioned and online within minutes." },
          { title: "40+ games", body: "Minecraft, Rust, Valheim, ARK, Palworld, CS2 and dozens more, all on one platform." },
        ],
        steps: [
          { title: "Pick your game", body: "Browse the full game-server catalog and choose a plan by player count." },
          { title: "Server goes live in minutes", body: "Instant provisioning with the right ports open." },
          { title: "Add mods and configs", body: "Full file access to install mods and drop in your own files." },
          { title: "Invite your players", body: `Share the connect string with your ${loc.audience} crew.` },
        ],
        specNote: `Most titles run happily on 4 GB for a small group; step up for bigger lobbies or heavy modpacks. Every server gets dedicated resources and DDoS protection.`,
        faq: [
          gameServerLocationFaq(loc, "game"),
          { q: `Which games can I host for ${loc.name}?`, a: "Minecraft, Rust, Valheim, Palworld, ARK, CS2, Garry's Mod, Project Zomboid, 7 Days to Die, Terraria, and dozens more — see the full game-servers catalog." },
          { q: "How much RAM does my game need?", a: "Light survival worlds are happy on 2-4 GB for a small group; big modpacks or large lobbies want 8 GB or more. Resize with one click any time." },
          { q: "Is DDoS protection included?", a: "Yes — always-on DDoS mitigation and a managed firewall come with every game server at no extra cost." },
          { q: "Can I install mods?", a: "Yes — full file access means you can install any mod loader or plugin your title supports." },
        ],
        related: generalRelatedLinks(combo),
      }
    : {
        eyebrow: `${flag} ${loc.name} VPS hosting`,
        title: `A cloud VPS built for`,
        highlight: loc.name,
        sub: `Full-root NVMe virtual servers ${lowPing ? "aimed at" : "for"} ${loc.regionLong} — a dedicated IPv4, always-on DDoS protection, daily backups and one-click deploys, from ${from}/mo.`,
        intro: [
          `If your users are in ${loc.name}, distance is latency and latency is money. ${loc.hub}`,
          `Nxeon's cloud VPS is the same full-root platform everywhere: enterprise NVMe on a self-healing ZFS mirror, a dedicated IPv4, always-on DDoS protection with a managed firewall, daily backups and snapshots, and one-click OS or app images live in about 47 seconds.`,
          `This page is tuned for ${loc.name} and the surrounding ${loc.audience} audience across ${near3}. Pick a size, deploy, point your domain, and scale with a one-click resize as your traffic grows.`,
        ],
        whyTitle: `Why Nxeon for a ${loc.name} VPS`,
        why: [
          { title: lowPing ? `Aimed at ${loc.name}` : `Priced for ${loc.name}`, body: lowPing ? `Copy, support and deploy guidance built around ${articleFor(loc.audience)} ${loc.audience} audience.` : `Region guidance for ${articleFor(loc.audience)} ${loc.audience} audience — pick your nearest of Singapore or Germany at checkout.` },
          { title: "Full root, your stack", body: "SSH in and run anything — Docker, databases, Node, control panels." },
          { title: "Enterprise NVMe on ZFS", body: "Fast, consistent storage on enterprise NVMe over a self-healing ZFS mirror." },
          { title: "Dedicated IPv4 + DDoS", body: "Your own IPv4 and always-on DDoS protection with a managed firewall on every plan." },
          { title: "~47-second deploys", body: "One-click OS and app images bring a server online in about 47 seconds." },
          { title: "One-click resize", body: `Add vCPU, RAM or disk without a rebuild as your ${loc.name} traffic grows.` },
        ],
        steps: [
          { title: "Create your account free", body: "No card required. Open the deploy wizard in seconds." },
          { title: "Choose an image", body: "Pick a one-click OS or app image — Ubuntu, Debian, Docker, WordPress and more." },
          { title: "Deploy & point your domain", body: `Your VPS is live in ~47 seconds with a dedicated IP.` },
          { title: "Tune and scale", body: "With full root you own the stack; one-click resize grows the box as demand does." },
        ],
        specNote: `Starter (2 GB) or Standard (4 GB) is a strong start for most sites and APIs; step up to Pro (8 GB) for busier apps. Every plan ships with a dedicated IP.`,
        faq: [
          gameServerLocationFaq(loc, "VPS"),
          { q: `Who is a ${loc.name} VPS best for?`, a: `Anyone serving ${loc.regionLong}: SaaS apps, business sites, APIs, bots and dashboards for ${articleFor(loc.audience)} ${loc.audience} audience.` },
          { q: "Do I get full root access?", a: "Yes — every VPS is full-root with SSH." },
          { q: "What's included in the price?", a: `Every plan includes enterprise NVMe on a ZFS mirror, a dedicated IPv4, always-on DDoS protection, a managed firewall, daily backups, snapshots, IPv6 and a 99.9% uptime SLA — from ${from}/mo.` },
          { q: "Can I upgrade later?", a: "Yes. A one-click resize adds vCPU, RAM or disk with no rebuild and no migration." },
        ],
        related: generalRelatedLinks(combo),
      };

  return { metaTitle, metaDescription, ogTitle: metaTitle, ogDescription: metaDescription, breadcrumbName: `${loc.name} ${isGame ? "Game Server Hosting" : "VPS Hosting"}`, content };
}

function fromLabelVps(plans: LandingPlan[]): string {
  if (!plans.length) return "$6.49";
  return money(Math.min(...plans.map((p) => planIntroMonthlyCents(p) ?? p.priceCents)));
}

